import{_ as s,c as i,G as a,b as e}from"./chunks/framework.BrC0DRXd.js";const t=JSON.parse('{"title":"使用 Netlify + MongoDB Atlas 自建 Twikoo 评论系统","description":"使用 Netlify Functions 和 MongoDB Atlas 为静态博客部署独立的 Twikoo 评论服务。本文从数据库创建、GitHub 仓库 Fork、Netlify 部署、环境变量配置到博客前端接入，记录完整操作流程及部署过程中遇到的常见问题。","frontmatter":{"title":"使用 Netlify + MongoDB Atlas 自建 Twikoo 评论系统","filename":2026111901,"tags":["Twikoo","Netlify","MongoDB","github","静态博客"],"categories":["技术分享"],"date":"2026-11-19T00:00:00.000Z","description":"使用 Netlify Functions 和 MongoDB Atlas 为静态博客部署独立的 Twikoo 评论服务。本文从数据库创建、GitHub 仓库 Fork、Netlify 部署、环境变量配置到博客前端接入，记录完整操作流程及部署过程中遇到的常见问题。","articleGPT":null,"cover":"https://picsum.org/1920/1080.jpg","top":null,"share":true,"delete":null,"head":[["link",{"rel":"canonical","href":"https://hongxi-hub.github.io//posts/2026111901"}]]},"headers":[],"relativePath":"posts/2026111901.md","filePath":"posts/2026111901.md","lastUpdated":1795106540000}');const n=s({name:"posts/2026111901.md"},[["render",function(s,t,n,l,o,p){return e(),i("div",null,t[0]||(t[0]=[a('<h1 id="使用-netlify-mongodb-atlas-自建-twikoo-评论系统" tabindex="-1">使用 Netlify + MongoDB Atlas 自建 Twikoo 评论系统 <a class="header-anchor" href="#使用-netlify-mongodb-atlas-自建-twikoo-评论系统" aria-label="Permalink to &quot;使用 Netlify + MongoDB Atlas 自建 Twikoo 评论系统&quot;">​</a></h1><p>对于使用 GitHub Pages 等静态托管平台搭建的博客，评论系统通常需要借助第三方服务提供后端支持。Twikoo 是一款适用于静态网站的评论系统，支持评论管理、邮件通知等功能，可以通过云函数与数据库实现评论数据的存储和读取。</p><p>本文采用 <strong>Netlify Functions + MongoDB Atlas</strong> 的方式部署 Twikoo 后端，前端继续使用博客主题提供的 Twikoo 评论组件。整个方案不需要购买服务器，后端代码托管在 GitHub，函数部署在 Netlify，评论数据存储于 MongoDB Atlas。</p><h2 id="一、方案概述" tabindex="-1">一、方案概述 <a class="header-anchor" href="#一、方案概述" aria-label="Permalink to &quot;一、方案概述&quot;">​</a></h2><h3 id="_1-1-技术架构" tabindex="-1">1.1 技术架构 <a class="header-anchor" href="#_1-1-技术架构" aria-label="Permalink to &quot;1.1 技术架构&quot;">​</a></h3><p>本方案涉及四个主要部分：</p><div class="table-container"><table><thead><tr><th>服务</th><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>GitHub</td><td>后端源码托管</td><td>Fork Twikoo 官方 Netlify 项目</td></tr><tr><td>Netlify</td><td>后端函数部署</td><td>提供 Twikoo 云函数接口</td></tr><tr><td>MongoDB Atlas</td><td>数据库存储</td><td>保存评论及相关数据</td></tr><tr><td>GitHub Pages</td><td>博客前端托管</td><td>展示评论组件并向后端发送请求</td></tr></tbody></table></div><p>整体运行流程如下：</p><ol><li>用户访问静态博客，浏览器加载 Twikoo 前端 JavaScript。</li><li>Twikoo 前端根据配置中的 <code>envId</code>，向 Netlify Functions 发送请求。</li><li>Netlify 云函数接收请求，调用 MongoDB Atlas。</li><li>MongoDB Atlas 完成评论数据的读取或写入。</li><li>云函数将结果返回给浏览器，评论组件更新页面内容。</li></ol><p>其中，GitHub Pages 只负责博客页面展示，不承担评论数据存储和后端处理工作。</p><h3 id="_1-2-为什么选择这种方案" tabindex="-1">1.2 为什么选择这种方案？ <a class="header-anchor" href="#_1-2-为什么选择这种方案" aria-label="Permalink to &quot;1.2 为什么选择这种方案？&quot;">​</a></h3><ul><li><strong>无需购买服务器</strong>：Netlify Functions 提供云函数运行环境，MongoDB Atlas 提供免费数据库资源。</li><li><strong>与静态博客兼容</strong>：不需要改变原有 GitHub Pages 部署方式。</li><li><strong>数据独立存储</strong>：评论数据保存在自己的 MongoDB 数据库中，不依赖原主题作者或其他第三方评论服务。</li><li><strong>后端独立管理</strong>：可以通过 Netlify 查看部署状态和函数日志，通过 Twikoo 管理界面管理评论。</li><li><strong>方便后续迁移</strong>：后端源码、部署服务和数据库相互独立，便于后续调整。</li></ul><p>需要注意，免费套餐存在资源、流量和使用限制，具体以各平台当前政策为准。</p><h3 id="_1-3-需要注册的服务" tabindex="-1">1.3 需要注册的服务 <a class="header-anchor" href="#_1-3-需要注册的服务" aria-label="Permalink to &quot;1.3 需要注册的服务&quot;">​</a></h3><ul><li><a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://www.mongodb.com/products/platform/atlas-database" target="_blank" rel="noreferrer">MongoDB Atlas</a></li><li><a href="https://www.netlify.com/" target="_blank" rel="noreferrer">Netlify</a></li></ul><h2 id="二、准备-mongodb-atlas-数据库" tabindex="-1">二、准备 MongoDB Atlas 数据库 <a class="header-anchor" href="#二、准备-mongodb-atlas-数据库" aria-label="Permalink to &quot;二、准备 MongoDB Atlas 数据库&quot;">​</a></h2><h3 id="_2-1-注册并创建数据库集群" tabindex="-1">2.1 注册并创建数据库集群 <a class="header-anchor" href="#_2-1-注册并创建数据库集群" aria-label="Permalink to &quot;2.1 注册并创建数据库集群&quot;">​</a></h3><ol><li>访问 <a href="https://www.mongodb.com/products/platform/atlas-database" target="_blank" rel="noreferrer">MongoDB Atlas</a>，注册并登录账户。</li><li>进入 Atlas 控制台，创建一个新的数据库集群。</li><li>选择 Free 免费套餐。</li><li>根据需要选择云服务商和区域。</li><li>完成创建，等待集群状态变为 <code>ACTIVE</code>。</li></ol><p>免费集群的具体配置和可选区域可能随平台政策调整，按照当前控制台提供的选项操作即可。</p><h3 id="_2-2-创建数据库用户" tabindex="-1">2.2 创建数据库用户 <a class="header-anchor" href="#_2-2-创建数据库用户" aria-label="Permalink to &quot;2.2 创建数据库用户&quot;">​</a></h3><p>进入数据库访问管理页面（Database Access），创建一个新的数据库用户。</p><p>需要注意：这里创建的是<strong>数据库用户</strong>，不是 MongoDB Atlas 网站的登录账户。</p><p>设置用户名和密码，并为其分配访问数据库所需的权限。建议遵循最小权限原则，不要使用不必要的管理员权限。</p><p>请妥善保存数据库用户名和密码，后续配置 Netlify 环境变量时需要使用。</p><h3 id="_2-3-配置网络访问权限" tabindex="-1">2.3 配置网络访问权限 <a class="header-anchor" href="#_2-3-配置网络访问权限" aria-label="Permalink to &quot;2.3 配置网络访问权限&quot;">​</a></h3><p>进入 Network Access 页面，配置数据库允许接受连接的 IP 地址。</p><p>Netlify Functions 的出口 IP 可能动态变化，因此不能简单地将某一个固定 IP 视为长期有效的访问来源。</p><p>一种常见的配置方式是添加：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.0.0.0/0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这表示允许所有 IPv4 地址尝试连接数据库。</p><p><strong>安全提醒：</strong> 这并不意味着数据库可以被无认证访问。数据库仍然需要正确的用户名、密码和权限控制。但开放所有来源会扩大可尝试连接的范围，因此必须使用强密码、限制数据库用户权限，并避免泄露连接字符串。若有条件，也可以进一步采用平台支持的网络访问限制方案。</p><h3 id="_2-4-获取-mongodb-连接字符串" tabindex="-1">2.4 获取 MongoDB 连接字符串 <a class="header-anchor" href="#_2-4-获取-mongodb-连接字符串" aria-label="Permalink to &quot;2.4 获取 MongoDB 连接字符串&quot;">​</a></h3><p>在集群页面点击 Connect，选择 Drivers，获取连接字符串。</p><p>其格式通常类似：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb+srv://&lt;db_username&gt;:&lt;db_password&gt;@&lt;cluster&gt;.mongodb.net/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>建议在连接字符串中指定数据库名称及连接参数，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb+srv://&lt;db_username&gt;:&lt;db_password&gt;@&lt;cluster&gt;.mongodb.net/twikoo?retryWrites=true&amp;w=majority</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中：</p><ul><li><code>&lt;db_username&gt;</code>：前面创建的数据库用户名。</li><li><code>&lt;db_password&gt;</code>：数据库用户密码。</li><li><code>&lt;cluster&gt;</code>：MongoDB 集群地址。</li><li><code>twikoo</code>：数据库名称，可按实际情况设置。</li></ul><p>如果密码包含 <code>@</code>、<code>#</code>、<code>/</code> 等特殊字符，需要进行 URL 编码，否则可能导致连接字符串解析失败。</p><p><strong>重要：MongoDB 连接字符串属于敏感凭据。不要将其写入 GitHub 仓库、博客前端配置文件或公开文档。</strong></p><h2 id="三、fork-twikoo-后端项目" tabindex="-1">三、Fork Twikoo 后端项目 <a class="header-anchor" href="#三、fork-twikoo-后端项目" aria-label="Permalink to &quot;三、Fork Twikoo 后端项目&quot;">​</a></h2><h3 id="_3-1-获取官方项目" tabindex="-1">3.1 获取官方项目 <a class="header-anchor" href="#_3-1-获取官方项目" aria-label="Permalink to &quot;3.1 获取官方项目&quot;">​</a></h3><p>Twikoo 官方 Netlify 后端项目：</p><p><a href="https://github.com/twikoojs/twikoo-netlify" target="_blank" rel="noreferrer">GitHub - twikoojs/twikoo-netlify</a></p><p>进入仓库后，点击右上角的 Fork，将项目复制到自己的 GitHub 账户下。</p><p>Fork 完成后，得到一个属于自己的后端源码仓库。</p><h3 id="_3-2-检查项目结构" tabindex="-1">3.2 检查项目结构 <a class="header-anchor" href="#_3-2-检查项目结构" aria-label="Permalink to &quot;3.2 检查项目结构&quot;">​</a></h3><p>Fork 完成后，可以在仓库中查看项目文件。</p><p>其中，<code>netlify/functions</code> 目录用于存放 Netlify Functions 云函数代码。部署时，Netlify 会识别并打包其中的函数。</p><p>通常不需要自行修改后端源码，按照官方项目提供的部署方式即可。</p><h2 id="四、使用-netlify-部署后端" tabindex="-1">四、使用 Netlify 部署后端 <a class="header-anchor" href="#四、使用-netlify-部署后端" aria-label="Permalink to &quot;四、使用 Netlify 部署后端&quot;">​</a></h2><h3 id="_4-1-导入-github-项目" tabindex="-1">4.1 导入 GitHub 项目 <a class="header-anchor" href="#_4-1-导入-github-项目" aria-label="Permalink to &quot;4.1 导入 GitHub 项目&quot;">​</a></h3><ol><li>访问 <a href="https://www.netlify.com/" target="_blank" rel="noreferrer">Netlify</a> 并登录。</li><li>选择从 Git 仓库导入项目（Import from Git）。</li><li>授权 Netlify 访问 GitHub。</li><li>选择刚才 Fork 的 <code>twikoo-netlify</code> 仓库。</li><li>按照项目默认配置完成导入。</li></ol><p>Netlify 会自动识别项目中的构建配置和 Functions 目录。若没有特殊需要，不必随意修改构建命令、发布目录等参数。</p><h3 id="_4-2-关于-netlify-界面变化" tabindex="-1">4.2 关于 Netlify 界面变化 <a class="header-anchor" href="#_4-2-关于-netlify-界面变化" aria-label="Permalink to &quot;4.2 关于 Netlify 界面变化&quot;">​</a></h3><p>实际操作时发现，当前 Netlify 控制台与部分 Twikoo 旧版操作教程中的界面存在较大差异。</p><p>尤其是项目设置、环境变量管理和部署相关入口，旧教程中的截图及菜单路径可能已经不再适用。当前界面还增加或调整了与 AI 工作流相关的产品入口和交互布局。</p><p>因此，建议以当前 Netlify 控制台实际显示的选项为准，不必机械套用旧教程中的菜单位置。</p><h3 id="_4-3-配置环境变量-mongodb-uri" tabindex="-1">4.3 配置环境变量 MONGODB_URI <a class="header-anchor" href="#_4-3-配置环境变量-mongodb-uri" aria-label="Permalink to &quot;4.3 配置环境变量 MONGODB_URI&quot;">​</a></h3><p>这是后端连接数据库最重要的一步。</p><p>进入 Netlify 项目设置，找到：</p><p><code>Project configuration</code> → <code>Environment variables</code> 或 <code>Keys and secrets</code></p><p>不同版本的控制台可能存在名称或入口差异。</p><p>新增环境变量：</p><div class="table-container"><table><thead><tr><th>变量名称</th><th>变量值</th></tr></thead><tbody><tr><td><code>MONGODB_URI</code></td><td>前面获取的 MongoDB 完整连接字符串</td></tr></tbody></table></div><p>例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MONGODB_URI=mongodb+srv://&lt;db_username&gt;:&lt;db_password&gt;@&lt;cluster&gt;.mongodb.net/twikoo?retryWrites=true&amp;w=majority</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意：</p><ul><li>变量名称必须准确填写为 <code>MONGODB_URI</code>。</li><li>变量值必须是完整的 MongoDB 连接字符串。</li><li>不要将连接字符串提交到 GitHub。</li><li>确认环境变量的适用范围包含 Functions 和 Runtime。</li></ul><p>配置完成后，保存环境变量。</p><p><strong>特别注意：</strong> 如果此前已经部署过项目，新增或修改环境变量后，建议重新触发一次部署，使新的部署环境能够正确读取配置。</p><h3 id="_4-4-重新部署项目" tabindex="-1">4.4 重新部署项目 <a class="header-anchor" href="#_4-4-重新部署项目" aria-label="Permalink to &quot;4.4 重新部署项目&quot;">​</a></h3><p>完成环境变量配置后，进入 Deploys 页面，触发重新部署。</p><p>部署过程中可以查看构建日志，重点检查：</p><ul><li>是否成功拉取 GitHub 仓库。</li><li>依赖安装是否成功。</li><li>是否识别到 <code>netlify/functions</code>。</li><li>是否成功打包 Twikoo 云函数。</li><li>最后是否显示部署成功，例如 <code>Site is live</code>。</li></ul><p>如果构建成功，Netlify 会为项目分配一个默认域名：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;site-name&gt;.netlify.app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个地址是后续前端配置需要使用的稳定生产域名。</p><h3 id="_4-5-测试云函数接口" tabindex="-1">4.5 测试云函数接口 <a class="header-anchor" href="#_4-5-测试云函数接口" aria-label="Permalink to &quot;4.5 测试云函数接口&quot;">​</a></h3><p>Twikoo 在 Netlify 中的函数接口路径为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;site-name&gt;.netlify.app/.netlify/functions/twikoo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将其粘贴到浏览器地址栏访问。</p><p>如果后端运行正常，通常会返回类似以下内容：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Twikoo 云函数运行正常，请参考 https://twikoo.js.org/frontend.html 完成前端的配置&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0.17&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这表示云函数能够正常响应健康检查请求。</p><p>但需要注意，<strong>接口返回 <code>code: 100</code> 并不等于已经完整验证 MongoDB 的评论读写功能</strong>。后续仍需要在博客前端实际发表评论，并检查刷新页面后能否正常读取。</p><h3 id="_4-6-注意区分生产域名和部署预览地址" tabindex="-1">4.6 注意区分生产域名和部署预览地址 <a class="header-anchor" href="#_4-6-注意区分生产域名和部署预览地址" aria-label="Permalink to &quot;4.6 注意区分生产域名和部署预览地址&quot;">​</a></h3><p>Netlify 可能为每次部署生成带有 Deploy ID 的预览地址。</p><p>例如，预览地址可能包含一串部署标识，而生产域名则通常为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;site-name&gt;.netlify.app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>两者用途不同：</p><ul><li>部署预览地址：用于检查某一次部署的临时结果。</li><li>生产域名：指向项目当前正式部署版本，适合长期使用。</li></ul><p><strong>博客前端的 <code>envId</code> 应使用稳定的生产域名，不要使用带有 Deploy ID 的临时预览地址。</strong></p><h2 id="五、配置博客前端" tabindex="-1">五、配置博客前端 <a class="header-anchor" href="#五、配置博客前端" aria-label="Permalink to &quot;五、配置博客前端&quot;">​</a></h2><h3 id="_5-1-找到主题配置文件" tabindex="-1">5.1 找到主题配置文件 <a class="header-anchor" href="#_5-1-找到主题配置文件" aria-label="Permalink to &quot;5.1 找到主题配置文件&quot;">​</a></h3><p>接下来需要修改博客主题的 Twikoo 配置，将评论请求指向刚刚部署的 Netlify 后端。</p><p>对于本文使用的 VitePress 主题，原始主题配置位于：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.vitepress/theme/assets/themeConfig.mjs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>主题支持通过在仓库根目录放置 <code>themeConfig.mjs</code> 来覆盖默认配置。</p><p>如果此前已经按照主题说明复制并修改过根目录下的 <code>themeConfig.mjs</code>，那么本次直接修改这个文件即可。</p><p><strong>不要为了配置 Twikoo 而额外创建重复的配置文件，也不要随意移动、删除或重命名已有配置文件。</strong></p><h3 id="_5-2-修改-twikoo-配置" tabindex="-1">5.2 修改 Twikoo 配置 <a class="header-anchor" href="#_5-2-修改-twikoo-配置" aria-label="Permalink to &quot;5.2 修改 Twikoo 配置&quot;">​</a></h3><p>在 <code>themeConfig.mjs</code> 中找到评论系统相关配置。</p><p>原始配置可能类似：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;twikoo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  artalk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    site</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  twikoo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    js</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mirrors.sustech.edu.cn/cdnjs/ajax/libs/twikoo/1.6.39/twikoo.all.min.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    envId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://原来的服务地址/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    lang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zh-CN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>其中几个参数的作用如下：</p><div class="table-container"><table><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>enable</code></td><td>是否启用评论功能</td></tr><tr><td><code>type</code></td><td>选择评论系统类型</td></tr><tr><td><code>js</code></td><td>Twikoo 前端 JavaScript 库地址</td></tr><tr><td><code>envId</code></td><td>Twikoo 后端云函数接口地址</td></tr><tr><td><code>region</code></td><td>腾讯云环境地域，非腾讯云部署通常留空</td></tr><tr><td><code>lang</code></td><td>评论组件语言</td></tr></tbody></table></div><p>将 <code>js</code> 和 <code>envId</code> 修改为新的配置：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;twikoo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  artalk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    site</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  twikoo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    js</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://cdn.jsdelivr.net/npm/twikoo@2.0.17/dist/twikoo.min.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    envId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://&lt;site-name&gt;.netlify.app/.netlify/functions/twikoo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    lang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zh-CN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>这里有两个关键点：</p><ol><li><code>js</code> 指向 Twikoo 前端 JavaScript 库，负责在浏览器中加载和运行评论组件。</li><li><code>envId</code> 指向刚才部署的 Netlify 云函数接口，决定评论数据请求发送到哪里。</li></ol><p><code>artalk</code> 是主题中预留的另一套评论系统配置。本文实际启用的是 Twikoo，因此不需要修改 Artalk 配置。</p><h3 id="_5-3-注意前后端版本一致性" tabindex="-1">5.3 注意前后端版本一致性 <a class="header-anchor" href="#_5-3-注意前后端版本一致性" aria-label="Permalink to &quot;5.3 注意前后端版本一致性&quot;">​</a></h3><p>原主题配置使用的 Twikoo 前端版本为 <code>1.6.39</code>，而新部署的后端返回版本为 <code>2.0.17</code>。</p><p>为了减少版本差异带来的兼容性风险，建议将前端 JavaScript 库也调整到与后端对应的版本。</p><p>本文示例采用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/npm/twikoo@2.0.17/dist/twikoo.min.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果使用其他 CDN，也应确认对应版本和文件路径有效。</p><p>需要说明的是，前后端版本不一致属于值得检查的兼容性问题，但不能仅凭版本差异就认定它是某次请求失败的原因。</p><h3 id="_5-4-提交并部署博客" tabindex="-1">5.4 提交并部署博客 <a class="header-anchor" href="#_5-4-提交并部署博客" aria-label="Permalink to &quot;5.4 提交并部署博客&quot;">​</a></h3><p>修改完成后，将 <code>themeConfig.mjs</code> 提交并推送到 GitHub。</p><p>GitHub Pages 的自动部署流程会重新构建博客。</p><p>部署完成后，访问博客文章页面，检查评论区是否正常加载。</p><h2 id="六、首次初始化管理员账户" tabindex="-1">六、首次初始化管理员账户 <a class="header-anchor" href="#六、首次初始化管理员账户" aria-label="Permalink to &quot;六、首次初始化管理员账户&quot;">​</a></h2><p>Twikoo 后端部署完成后，还需要初始化评论管理账户。</p><ol><li>打开博客中任意一篇文章。</li><li>找到页面底部的 Twikoo 评论区。</li><li>点击评论管理入口，通常表现为齿轮或管理图标。</li><li>按照页面提示首次设置管理员密码。</li><li>设置完成后，进入管理界面。</li></ol><p>管理员密码用于管理评论，不等同于 MongoDB 数据库密码，也不应与数据库用户凭据混用。</p><p>完成初始化后，可以通过管理界面对评论进行审核、删除等操作。</p><p>需要注意，Twikoo 管理面板负责评论管理，MongoDB Atlas 负责底层数据存储，Netlify 则负责后端函数部署和运行。三者的功能不同。</p><h2 id="七、部署过程中遇到的问题及排查方法" tabindex="-1">七、部署过程中遇到的问题及排查方法 <a class="header-anchor" href="#七、部署过程中遇到的问题及排查方法" aria-label="Permalink to &quot;七、部署过程中遇到的问题及排查方法&quot;">​</a></h2><p>以下问题均来自本次实际部署过程，其中部分是已经定位并解决的故障，另一些则是部署时需要特别注意的配置问题。</p><h3 id="_7-1-提示未设置环境变量-mongodb-uri" tabindex="-1">7.1 提示未设置环境变量 MONGODB_URI <a class="header-anchor" href="#_7-1-提示未设置环境变量-mongodb-uri" aria-label="Permalink to &quot;7.1 提示未设置环境变量 MONGODB_URI&quot;">​</a></h3><p><strong>出现的问题：</strong></p><p>首次访问 Netlify 云函数接口时，返回：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;未设置环境变量 MONGODB_URI&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>原因分析：</strong></p><p>后端函数没有读取到名为 <code>MONGODB_URI</code> 的环境变量。</p><p>这通常与环境变量尚未配置、名称填写错误、适用范围不正确，或者部署环境尚未更新有关。</p><p><strong>解决方法：</strong></p><ol><li>进入 Netlify 项目设置。</li><li>找到 <code>Keys and secrets</code> 或环境变量管理页面。</li><li>检查是否存在 <code>MONGODB_URI</code>。</li><li>确认变量值是完整的 MongoDB 连接字符串。</li><li>确认变量适用范围包含 Functions 和 Runtime。</li><li>保存后重新部署项目。</li><li>再次访问云函数接口，检查是否恢复正常。</li></ol><p><strong>经验：</strong> 环境变量配置完成后，不要只停留在保存操作，还应重新部署并通过接口测试确认函数能够正常读取。</p><h3 id="_7-2-误用-netlify-部署预览地址" tabindex="-1">7.2 误用 Netlify 部署预览地址 <a class="header-anchor" href="#_7-2-误用-netlify-部署预览地址" aria-label="Permalink to &quot;7.2 误用 Netlify 部署预览地址&quot;">​</a></h3><p><strong>出现的问题：</strong></p><p>部署完成后，Netlify 提供了多个可访问地址，其中包括带有部署标识的预览地址。</p><p>初期容易将预览地址误认为长期使用的云函数地址。</p><p><strong>原因分析：</strong></p><p>Netlify 的部署预览地址与项目正式生产域名不是同一个概念。预览地址通常对应某一次具体部署，不适合作为长期固定的后端接口地址。</p><p><strong>解决方法：</strong></p><p>进入 Netlify 项目主页，找到正式生产站点域名，并在其后添加函数路径：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;site-name&gt;.netlify.app/.netlify/functions/twikoo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将该地址填写到博客配置文件的 <code>envId</code> 中。</p><h3 id="_7-3-评论区提示-failed-to-fetch-跨域请求失败" tabindex="-1">7.3 评论区提示 Failed to fetch，跨域请求失败 <a class="header-anchor" href="#_7-3-评论区提示-failed-to-fetch-跨域请求失败" aria-label="Permalink to &quot;7.3 评论区提示 Failed to fetch，跨域请求失败&quot;">​</a></h3><p><mark>本次部署中最关键的一次故障排查。</mark></p><p><strong>出现的问题：</strong></p><p>博客评论区无法正常加载或提交评论，浏览器控制台提示：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Failed to fetch</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>页面同时提示请求被跨域策略拦截。</p><p><strong>排查过程：</strong></p><p>打开浏览器开发者工具，进入 Network，检查 Twikoo 请求。</p><p>发现请求信息如下：</p><div class="table-container"><table><thead><tr><th>项目</th><th>实际情况</th></tr></thead><tbody><tr><td>Request URL</td><td>Netlify Twikoo Function 地址</td></tr><tr><td>Request Method</td><td><code>OPTIONS</code></td></tr><tr><td>Status Code</td><td><code>401 Unauthorized</code></td></tr><tr><td>Server</td><td><code>Netlify</code></td></tr><tr><td>Origin</td><td>博客域名</td></tr><tr><td>Access-Control-Request-Method</td><td><code>POST</code></td></tr><tr><td>Access-Control-Request-Headers</td><td><code>content-type</code></td></tr></tbody></table></div><p>这里最重要的信息是：失败的请求并不是实际提交评论的 <code>POST</code>，而是浏览器首先发送的跨域预检请求 <code>OPTIONS</code>。</p><p>由于浏览器需要在正式发送跨域 POST 请求前确认服务器是否允许该请求，因此预检请求失败后，浏览器不会继续发送实际 POST 请求，最终评论组件表现为 <code>Failed to fetch</code>。</p><p><strong>原因定位：</strong></p><p>检查 Netlify 项目设置后，发现项目的 <code>Project visibility</code> 被设置为 <code>Private</code>。</p><p>也就是说，问题并非 MongoDB 连接失败，也不能简单归因于 Twikoo 本身的 CORS 配置，而是 Netlify 项目的访问可见性设置阻止了外部请求。</p><p><strong>解决方法：</strong></p><p>进入 Netlify 项目设置，找到项目访问权限相关配置：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Project configuration</span></span>\n<span class="line"><span>→ General</span></span>\n<span class="line"><span>→ Visitor access</span></span>\n<span class="line"><span>→ Project visibility</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>将项目可见性从 <code>Private</code> 调整为 <code>Public</code>。</p><p>不同版本的 Netlify 控制台可能会调整菜单名称和位置，实际操作时以当前界面为准。</p><p>修改完成后重新访问博客，评论请求恢复正常。</p><p><strong>经验总结：</strong></p><ul><li>Netlify 项目的 <code>Private</code> 与 <code>Public</code> 会影响外部访问部署内容和函数的能力。</li><li>对于需要由公开博客直接调用的 Twikoo 云函数，项目应允许外部访问。</li><li>将 Netlify 项目设置为 <code>Public</code>，不等于将 MongoDB 数据库连接字符串公开。</li><li>GitHub 仓库是否公开与 Netlify 项目是否允许公众访问，是两项不同的设置。</li></ul><p>遇到 <code>Failed to fetch</code> 时，不要直接认定是数据库故障。应先打开浏览器 Network，检查失败请求的类型和状态码。</p><p>尤其要区分：</p><ul><li><code>OPTIONS</code> 返回 <code>401</code>：优先检查 Netlify 项目访问权限。</li><li><code>POST</code> 请求失败：再检查函数运行日志、环境变量、数据库连接和请求内容。</li><li>接口直接返回 <code>code: 1000</code>：检查 <code>MONGODB_URI</code> 环境变量。</li></ul><h3 id="_7-4-前后端-twikoo-版本不一致" tabindex="-1">7.4 前后端 Twikoo 版本不一致 <a class="header-anchor" href="#_7-4-前后端-twikoo-版本不一致" aria-label="Permalink to &quot;7.4 前后端 Twikoo 版本不一致&quot;">​</a></h3><p><strong>出现的问题：</strong></p><p>原主题使用的前端 Twikoo 版本为 <code>1.6.39</code>，而新部署的后端版本为 <code>2.0.17</code>。</p><p><strong>原因分析：</strong></p><p>前端 JavaScript 库和后端云函数属于同一套评论系统的不同组成部分。版本差异可能带来兼容性问题。</p><p><strong>解决方法：</strong></p><p>检查前端 <code>js</code> 配置，尽量与后端版本保持一致。</p><p>本文使用的配置为：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">js</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://cdn.jsdelivr.net/npm/twikoo@2.0.17/dist/twikoo.min.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>需要注意，这一项属于版本兼容性检查，并非已经证实的 <code>Failed to fetch</code> 故障原因。本次跨域故障最终定位为 Netlify 项目设置为 <code>Private</code>。</p><h3 id="_7-5-找错主题配置文件" tabindex="-1">7.5 找错主题配置文件 <a class="header-anchor" href="#_7-5-找错主题配置文件" aria-label="Permalink to &quot;7.5 找错主题配置文件&quot;">​</a></h3><p><strong>出现的问题：</strong></p><p>主题原始配置文件位于：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.vitepress/theme/assets/themeConfig.mjs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但主题支持将配置复制到仓库根目录，通过根目录的 <code>themeConfig.mjs</code> 覆盖默认设置。</p><p>如果此前已经在根目录完成过主题配置修改，那么本次应该继续修改根目录文件。</p><p><strong>解决方法：</strong></p><p>先检查自己的仓库结构和已有配置，不要仅凭主题原始文件所在位置判断实际生效的配置文件。</p><p>本次使用的配置文件为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>themeConfig.mjs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>即仓库根目录下的文件。</p><p><strong>经验：</strong> 修改主题配置前，先确认项目实际使用的配置文件路径。不要因为教程中的路径与自己的项目不同，就额外创建一个同名配置文件。</p><h3 id="_7-6-数据库账号与-atlas-登录账号混淆" tabindex="-1">7.6 数据库账号与 Atlas 登录账号混淆 <a class="header-anchor" href="#_7-6-数据库账号与-atlas-登录账号混淆" aria-label="Permalink to &quot;7.6 数据库账号与 Atlas 登录账号混淆&quot;">​</a></h3><p>MongoDB Atlas 中存在两类容易混淆的账号：</p><ul><li>Atlas 登录账号：用于登录 MongoDB 网站和管理控制台。</li><li>Database Access 用户：用于应用程序连接数据库。</li></ul><p>Netlify 的 <code>MONGODB_URI</code> 应使用 Database Access 中创建的数据库用户名和密码，而不是 Atlas 网站登录凭据。</p><p>如果连接字符串中的账号使用错误，即使 Atlas 网站能够正常登录，也可能无法建立数据库连接。</p><h3 id="_7-7-接口健康检查成功-但评论仍不能正常读写" tabindex="-1">7.7 接口健康检查成功，但评论仍不能正常读写 <a class="header-anchor" href="#_7-7-接口健康检查成功-但评论仍不能正常读写" aria-label="Permalink to &quot;7.7 接口健康检查成功，但评论仍不能正常读写&quot;">​</a></h3><p>如果直接访问云函数接口返回：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Twikoo 云函数运行正常&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>只能说明云函数能够正常响应健康检查。</p><p>这不代表已经完整验证了：</p><ul><li>MongoDB 数据库连接是否稳定。</li><li>评论是否成功写入数据库。</li><li>评论能否在刷新后重新读取。</li><li>不同访客是否能正常访问评论数据。</li></ul><p>因此，接口健康检查通过后，还需要进行真实的评论读写测试。</p><h2 id="八、部署完成后的检查清单" tabindex="-1">八、部署完成后的检查清单 <a class="header-anchor" href="#八、部署完成后的检查清单" aria-label="Permalink to &quot;八、部署完成后的检查清单&quot;">​</a></h2><p>建议按以下顺序检查整个系统。</p><h3 id="_8-1-后端检查" tabindex="-1">8.1 后端检查 <a class="header-anchor" href="#_8-1-后端检查" aria-label="Permalink to &quot;8.1 后端检查&quot;">​</a></h3><ul><li>[ ] MongoDB Atlas 集群状态正常。</li><li>[ ] 已创建 Database Access 数据库用户。</li><li>[ ] 网络访问规则允许 Netlify Functions 连接。</li><li>[ ] Netlify 已配置 <code>MONGODB_URI</code>。</li><li>[ ] 环境变量适用范围包含 Functions 和 Runtime。</li><li>[ ] Netlify 项目允许公众访问。</li><li>[ ] Netlify 最新部署成功。</li><li>[ ] Twikoo Function 接口返回正常健康检查信息。</li></ul><h3 id="_8-2-前端检查" tabindex="-1">8.2 前端检查 <a class="header-anchor" href="#_8-2-前端检查" aria-label="Permalink to &quot;8.2 前端检查&quot;">​</a></h3><ul><li>[ ] 博客配置文件中的 <code>type</code> 为 <code>twikoo</code>。</li><li>[ ] 前端 <code>js</code> 地址有效。</li><li>[ ] <code>envId</code> 使用稳定生产域名。</li><li>[ ] <code>envId</code> 包含完整的 <code>/.netlify/functions/twikoo</code> 路径。</li><li>[ ] 前端和后端版本已检查。</li><li>[ ] GitHub Pages 已完成重新部署。</li><li>[ ] 博客文章页面能够正常加载评论区。</li></ul><h3 id="_8-3-评论功能检查" tabindex="-1">8.3 评论功能检查 <a class="header-anchor" href="#_8-3-评论功能检查" aria-label="Permalink to &quot;8.3 评论功能检查&quot;">​</a></h3><ul><li>[ ] 能够首次设置管理员密码。</li><li>[ ] 能够进入评论管理界面。</li><li>[ ] 能够正常发表测试评论。</li><li>[ ] 刷新页面后，已发表的评论仍然存在。</li><li>[ ] 使用无痕窗口或其他访客环境测试评论读取和提交。</li><li>[ ] 管理员能够正常管理测试评论。</li></ul><h2 id="九、数据管理与安全注意事项" tabindex="-1">九、数据管理与安全注意事项 <a class="header-anchor" href="#九、数据管理与安全注意事项" aria-label="Permalink to &quot;九、数据管理与安全注意事项&quot;">​</a></h2><h3 id="_9-1-妥善保管数据库连接字符串" tabindex="-1">9.1 妥善保管数据库连接字符串 <a class="header-anchor" href="#_9-1-妥善保管数据库连接字符串" aria-label="Permalink to &quot;9.1 妥善保管数据库连接字符串&quot;">​</a></h3><p><code>MONGODB_URI</code> 包含数据库访问凭据，应当只保存在 Netlify 的环境变量中。</p><p>不要：</p><ul><li>将完整连接字符串写入 GitHub 仓库。</li><li>将数据库用户名和密码写入前端 JavaScript。</li><li>在公开教程、截图或博客文章中展示真实连接字符串。</li><li>将包含密码的连接字符串发送给他人。</li></ul><p>如果怀疑凭据泄露，应及时修改数据库用户密码，并同步更新 Netlify 环境变量。</p><h3 id="_9-2-区分不同平台的管理职责" tabindex="-1">9.2 区分不同平台的管理职责 <a class="header-anchor" href="#_9-2-区分不同平台的管理职责" aria-label="Permalink to &quot;9.2 区分不同平台的管理职责&quot;">​</a></h3><div class="table-container"><table><thead><tr><th>平台</th><th>管理内容</th></tr></thead><tbody><tr><td>GitHub</td><td>后端源码及版本管理</td></tr><tr><td>Netlify</td><td>云函数部署、环境变量、运行日志和项目访问权限</td></tr><tr><td>MongoDB Atlas</td><td>数据库、数据库用户、网络访问规则及数据存储</td></tr><tr><td>Twikoo 管理界面</td><td>评论审核、删除和其他评论管理操作</td></tr></tbody></table></div><p>不要将 Netlify 的项目访问权限、GitHub 仓库可见性和 MongoDB 数据库访问权限混为一谈。</p><h3 id="_9-3-定期备份评论数据" tabindex="-1">9.3 定期备份评论数据 <a class="header-anchor" href="#_9-3-定期备份评论数据" aria-label="Permalink to &quot;9.3 定期备份评论数据&quot;">​</a></h3><p>评论数据保存在 MongoDB Atlas 中，而不是 GitHub Pages。</p><p>建议定期检查数据库状态，并根据评论数据的重要程度建立备份机制。</p><p>可以考虑使用 MongoDB 提供的数据导出工具，或者使用其他可靠方式备份数据库。</p><h3 id="_9-4-留意免费套餐限制" tabindex="-1">9.4 留意免费套餐限制 <a class="header-anchor" href="#_9-4-留意免费套餐限制" aria-label="Permalink to &quot;9.4 留意免费套餐限制&quot;">​</a></h3><p>Netlify 和 MongoDB Atlas 的免费套餐均有相应的资源与使用限制。</p><p>如果博客访问量较大，或者评论数量持续增加，应定期检查：</p><ul><li>Netlify Functions 的调用量和运行情况。</li><li>MongoDB Atlas 的存储空间和连接情况。</li><li>数据库的读写负载。</li><li>平台免费套餐的最新使用限制。</li></ul><p>免费套餐的具体额度可能发生变化，不应将某一时期的额度视为永久不变。</p><h2 id="十、参考资料" tabindex="-1">十、参考资料 <a class="header-anchor" href="#十、参考资料" aria-label="Permalink to &quot;十、参考资料&quot;">​</a></h2><ol><li><a href="https://twikoo.js.org/" target="_blank" rel="noreferrer">Twikoo 官方文档</a></li><li><a href="https://twikoo.js.org/frontend.html" target="_blank" rel="noreferrer">Twikoo 前端配置说明</a></li><li><a href="https://github.com/twikoojs/twikoo-netlify" target="_blank" rel="noreferrer">Twikoo Netlify 后端项目</a></li><li><a href="https://docs.netlify.com/" target="_blank" rel="noreferrer">Netlify 官方文档</a></li><li><a href="https://www.mongodb.com/docs/atlas/" target="_blank" rel="noreferrer">MongoDB Atlas 官方文档</a></li></ol><hr><h1 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h1><p>通过 GitHub、Netlify 和 MongoDB Atlas，可以为原本使用静态托管的博客搭建一套独立的 Twikoo 评论服务。</p><p>整个过程的核心在于三个环节：</p><ol><li><strong>数据库连接</strong>：在 MongoDB Atlas 创建数据库用户，并将完整连接字符串配置到 Netlify 的 <code>MONGODB_URI</code> 环境变量中。</li><li><strong>后端部署</strong>：将 Twikoo 官方 Netlify 项目 Fork 到自己的 GitHub 仓库，再导入 Netlify 完成部署。</li><li><strong>前端接入</strong>：修改博客主题配置中的 Twikoo <code>js</code> 和 <code>envId</code>，使评论组件指向新的后端接口。</li></ol><p>本次部署中最值得记录的经验是：评论区出现 <code>Failed to fetch</code> 时，应优先检查浏览器 Network 中失败请求的具体类型和状态码。此次故障最终并非由数据库或评论组件本身引起，而是 Netlify 项目设置为 <code>Private</code>，导致浏览器跨域预检请求返回 <code>401 Unauthorized</code>。将项目可见性调整为 <code>Public</code> 后，评论功能恢复正常。</p><p>对于静态博客而言，这种方案能够在保留原有前端部署方式的基础上，实现评论服务和数据存储的独立管理。</p><h3 id="ai-辅助创作声明" tabindex="-1">AI 辅助创作声明 <a class="header-anchor" href="#ai-辅助创作声明" aria-label="Permalink to &quot;AI 辅助创作声明&quot;">​</a></h3><p>本文在撰写过程中使用了 AI 对话工具辅助内容整理、文字组织与表达优化。文中观点、技术实践过程及最终内容均经过作者审阅和核对，作者对文章内容负责。</p>',249)]))}]]);export{t as __pageData,n as default};
